using System;using System.Collections.Generic;class CloneSlice{public readonly Dictionary<string,RebirthStationRecipeDiscoveryRecord> RecipeDiscoveries = new Dictionary<string,RebirthStationRecipeDiscoveryRecord>(StringComparer.Ordinal);public CloneSlice Clone(){var copy=new CloneSlice();foreach(var pair in RecipeDiscoveries) copy.RecipeDiscoveries.Add(pair.Key,pair.Value.Clone());return copy;}}